CREATE SCHEMA s1;
CREATE TABLE p(id INT PRIMARY KEY, u INT UNIQUE, c INT CONSTRAINT c_pos CHECK (c > 0), n TEXT NOT NULL, w INT, CONSTRAINT w_range CHECK (w <> c));
CREATE TABLE pk2(a INT, b INT, z INT, PRIMARY KEY (a, b), CONSTRAINT pk2_bz UNIQUE (b, z) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE f(x INT CONSTRAINT f_fk REFERENCES p ON DELETE CASCADE ON UPDATE SET NULL, y INT, z INT NOT NULL, q INT REFERENCES p (u), CONSTRAINT f_pk2 FOREIGN KEY (z, y) REFERENCES pk2 (b, a) ON DELETE RESTRICT);
CREATE TABLE s1.g(id INT CONSTRAINT g_key PRIMARY KEY, pid INT REFERENCES p);
CREATE TABLE nn(a INT NOT NULL, b INT, CONSTRAINT nn_b UNIQUE NULLS NOT DISTINCT (b));
CREATE TABLE longtablenamexxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx(longcolumnnameyyyyyyyyyyyyyyyyyyyyyyyy INT NOT NULL);
SELECT constraint_schema, constraint_name, table_schema, table_name, constraint_type, is_deferrable, initially_deferred, enforced, nulls_distinct FROM information_schema.table_constraints WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name, constraint_name;
SELECT constraint_schema, constraint_name, check_clause FROM information_schema.check_constraints WHERE constraint_schema IN ('public', 's1') ORDER BY constraint_schema, constraint_name;
SELECT constraint_schema, constraint_name, table_schema, table_name, column_name, ordinal_position, position_in_unique_constraint FROM information_schema.key_column_usage WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name, constraint_name, ordinal_position;
SELECT * FROM information_schema.referential_constraints WHERE constraint_schema IN ('public', 's1') ORDER BY constraint_schema, constraint_name;
SELECT * FROM information_schema.constraint_column_usage WHERE constraint_schema IN ('public', 's1') ORDER BY constraint_schema, constraint_name, table_name, column_name;
SELECT * FROM information_schema.constraint_table_usage WHERE constraint_schema IN ('public', 's1') ORDER BY constraint_schema, constraint_name, table_name;
CREATE DOMAIN dpos AS INT CHECK (VALUE > 0);
CREATE DOMAIN dnn AS BIGINT NOT NULL;
CREATE DOMAIN dboth AS SMALLINT NOT NULL CHECK (VALUE <= 100);
SELECT * FROM information_schema.domains WHERE domain_schema = 'public' ORDER BY domain_name;
SELECT * FROM information_schema.domain_constraints WHERE domain_schema = 'public' ORDER BY constraint_name;
SELECT * FROM information_schema.check_constraints WHERE constraint_name LIKE 'd%' ORDER BY constraint_name;
SELECT * FROM information_schema.domain_udt_usage WHERE domain_schema = 'public' ORDER BY domain_name;
SELECT * FROM information_schema.domains WHERE domain_schema = 'information_schema' ORDER BY domain_name;
SELECT * FROM information_schema.domain_constraints WHERE domain_schema = 'information_schema' ORDER BY constraint_name;
SELECT * FROM information_schema.check_constraints WHERE constraint_schema = 'information_schema' ORDER BY constraint_name;
SELECT * FROM information_schema.domain_udt_usage WHERE domain_schema = 'information_schema' ORDER BY domain_name;
SELECT * FROM information_schema.usage_privileges WHERE object_type = 'DOMAIN' ORDER BY object_schema, object_name, grantee;
SELECT * FROM information_schema.data_type_privileges WHERE object_type = 'DOMAIN' ORDER BY object_schema, object_name;
